```json
{
  "root_causes": [
    {
      "service": "cart",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS src, count(*) AS spans FROM abnormal_traces WHERE service_name='cart' UNION ALL SELECT 'norm', count(*) FROM normal_traces WHERE service_name='cart'",
          "claim": "Cart emits zero server spans in the abnormal window, versus 448 in the normal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration/1e6),2) AS avg_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.CartService/GetCart' GROUP BY ALL",
          "claim": "All 22 checkout calls to CartService/GetCart return Error in about 0.1–0.3 ms, with no cart-side span."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration/1e6),2) AS avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE 'grpc.oteldemo.CartService/%' GROUP BY ALL",
          "claim": "Every frontend gRPC call to CartService (AddItem, GetCart) errors in the abnormal window, 106 of 106."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name AS pod, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'cart-%' ORDER BY time",
          "claim": "The cart container restart counter steps from 0 to 1 at about 10:38:25, the start of the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "cart",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='checkout' GROUP BY ALL",
          "claim": "Checkout PlaceOrder and GetCart spans error 22 of 22 times, while checkout's other downstream calls are absent."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL",
          "claim": "Frontend PlaceOrder client calls and POST /api/checkout all return 500 in the abnormal window, 22 of 22."
        }
      ]
    },
    {
      "from": "cart",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('GET /api/cart','POST /api/cart') GROUP BY ALL",
          "claim": "Frontend /api/cart GET and POST requests return HTTP 500 for every request in the abnormal window."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns 500 for 156 requests in the abnormal window, against 30 errors in normal."
        }
      ]
    }
  ]
}
```

